<?php
require_once __DIR__ . '/../includes/functions.php';require_admin();$pageTitle='Панель администратора — Лесная гавань';
$rooms=(int)$pdo->query("SELECT COUNT(*) FROM accommodations WHERE status='active'")->fetchColumn();$bookings=(int)$pdo->query('SELECT COUNT(*) FROM bookings')->fetchColumn();$users=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='user'")->fetchColumn();$revenue=(float)$pdo->query("SELECT COALESCE(SUM(total_price),0) FROM bookings WHERE status IN ('confirmed','completed')")->fetchColumn();
$recent=$pdo->query('SELECT b.*,u.full_name,a.title FROM bookings b JOIN users u ON u.id=b.user_id JOIN accommodations a ON a.id=b.accommodation_id ORDER BY b.created_at DESC LIMIT 6')->fetchAll();
include __DIR__.'/../includes/header.php';
?>
<section class="container admin-page"><div class="admin-heading"><div><span class="eyebrow">УПРАВЛЕНИЕ БАЗОЙ</span><h1>Панель администратора</h1><p>Основные показатели и последние заявки.</p></div><div class="admin-actions"><a class="btn btn-outline-green" href="/admin/accommodations.php">Варианты проживания</a><a class="btn btn-green" href="/admin/bookings.php">Все бронирования</a></div></div><div class="stats-grid"><article class="stat-card"><span>⌂</span><strong><?= $rooms ?></strong><small>Активных вариантов</small></article><article class="stat-card"><span>▤</span><strong><?= $bookings ?></strong><small>Всего бронирований</small></article><article class="stat-card"><span>₽</span><strong><?= number_format($revenue,0,',',' ') ?></strong><small>Выручка, руб.</small></article><article class="stat-card"><span>♧</span><strong><?= $users ?></strong><small>Пользователей</small></article></div><div class="admin-table-wrap"><div class="table-heading"><h2>Последние заявки</h2><a class="text-link" href="/admin/bookings.php">Открыть все →</a></div><?php if($recent): ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>№</th><th>Гость</th><th>Проживание</th><th>Период</th><th>Сумма</th><th>Статус</th></tr></thead><tbody><?php foreach($recent as $b): ?><tr><td>#<?= (int)$b['id'] ?></td><td><?= e($b['full_name']) ?></td><td><?= e($b['title']) ?></td><td><?= date('d.m.Y',strtotime($b['check_in'])) ?> – <?= date('d.m.Y',strtotime($b['check_out'])) ?></td><td><?= number_format((float)$b['total_price'],0,',',' ') ?> ₽</td><td><span class="status-pill <?= e(booking_status_class($b['status'])) ?>"><?= e(booking_status_label($b['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="text-muted">Заявок пока нет.</p><?php endif; ?></div></section>
